What does this program print?#include <stdio.h>

void swap(int a, int b) {
    int t = a;
    a = b;
    b = t;
}

int main(void) {
    int x = 1, y = 2;
    swap(x, y);
    printf(&quot;%d %d\n&quot;, x, y);
    return 0;
}

