What does this program print?#include <stdio.h>

int f(int n) {
    return (n < 2) ? n : f(n - 1) + f(n - 2);
}

int main(void) {
    printf(&quot;%d\n&quot;, f(6));
    return 0;
}

What does this program print?#include <stdio.h>

int f(int n, int *c) {
    (*c)++;
    if (n <= 1) return 1;
    return f(n - 1, c) + f(n - 2, c);
}

int main(void) {
    int c = 0;
    f(5, &c);
    printf(&quot;%d\n&quot;, c);
    return 0;
}
